--
-- Table structure for table `stocks`
--

DROP TABLE IF EXISTS `stocks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `stocks` (
  `region` varchar(20) NOT NULL COMMENT '市场代码：GB=指数，SH=上证，SZ=深证，HK=港股',
  `code` varchar(20) NOT NULL COMMENT '股票代码',
  `name` varchar(50) DEFAULT NULL COMMENT '股票名称',
  `zxj` float DEFAULT NULL COMMENT '最新价',
  `zdf` float DEFAULT NULL COMMENT '涨跌幅',
  `zde` float DEFAULT NULL COMMENT '涨跌额',
  `cjl` float DEFAULT NULL COMMENT '成交量',
  `cje` float DEFAULT NULL COMMENT '成交额',
  `syl_dt` float DEFAULT NULL COMMENT '市盈率-动态',
  `sjl` float DEFAULT NULL COMMENT '市净率',
  `zsz` float DEFAULT NULL COMMENT '总市值',
  `ltsz` float DEFAULT NULL COMMENT '流通市值',
  `zdf_60d` float DEFAULT NULL COMMENT '60日涨跌幅',
  `zdf_nzj` float DEFAULT NULL COMMENT '年初至今涨跌幅',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`region`,`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

