--
-- Table structure for table `stocks_analyse`
--

DROP TABLE IF EXISTS `stocks_analyse`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `stocks_analyse` (
  `region` varchar(20) NOT NULL COMMENT '市场代码：GB=指数，SH=上证，SZ=深证，HK=港股',
  `code` varchar(20) NOT NULL COMMENT '股票代码',
  `name` varchar(50) DEFAULT NULL COMMENT '股票名称',
  `zsz` float DEFAULT NULL COMMENT '总市值',
  `ltsz` float DEFAULT NULL COMMENT '流通市值',
  `syl_dt` float DEFAULT NULL COMMENT '市盈率-动态',
  `sjl` float DEFAULT NULL COMMENT '市净率',
  `zxj` float DEFAULT NULL COMMENT '最新价',
  `zdf_60d` float DEFAULT NULL COMMENT '60日涨跌幅',
  `zdf_nzj` float DEFAULT NULL COMMENT '年初至今涨跌幅',
  `mgsy` float DEFAULT NULL COMMENT '每股收益',
  `yysr_yysr` float DEFAULT NULL COMMENT '营业收入-营业收入',
  `yysr_tbzz` float DEFAULT NULL COMMENT '营业收入-同比增长',
  `yysr_jdhbzz` float DEFAULT NULL COMMENT '营业收入-季度环比增长',
  `jlr_jlr` float DEFAULT NULL COMMENT '净利润-净利润',
  `jlr_tbzz` float DEFAULT NULL COMMENT '净利润-同比增长',
  `jlr_jdhbzz` float DEFAULT NULL COMMENT '净利润-季度环比增长',
  `mgjzc` float DEFAULT NULL COMMENT '每股净资产',
  `jzcsyl` float DEFAULT NULL COMMENT '净资产收益率',
  `mgjyxjll` float DEFAULT NULL COMMENT '每股经营现金流量',
  `xsmll` float DEFAULT NULL COMMENT '销售毛利率',
  `schy` varchar(50) DEFAULT NULL COMMENT '所处行业',
  `report_date` varchar(50) DEFAULT NULL COMMENT '报告日期',
  `update_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`region`,`code`),
  KEY `idx_stocks_analyse_unique` (`region`,`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

