--
-- Table structure for table `stocks_kline`
--

DROP TABLE IF EXISTS `stocks_kline`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `stocks_kline` (
  `region` varchar(20) NOT NULL COMMENT '市场代码：GB=指数，SH=上证，SZ=深证，HK=港股',
  `code` varchar(20) NOT NULL COMMENT '股票代码',
  `name` varchar(50) DEFAULT NULL COMMENT '股票名称',
  `zxj` float DEFAULT NULL COMMENT '最新价',
  `cjl` float DEFAULT NULL COMMENT '成交量',
  `cje` float DEFAULT NULL COMMENT '成交额',
  `zg` float DEFAULT NULL COMMENT '最高',
  `zd` float DEFAULT NULL COMMENT '最低',
  `jk` float DEFAULT NULL COMMENT '今开',
  `report_time` datetime NOT NULL COMMENT '报告时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`region`,`code`,`report_time`),
  KEY `idx_kline_unique` (`region`,`code`,`report_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
